causeCounts = aq.from(surveyResults)
  .select("cause")
  .groupby("cause")
  .count()
  .derive({ measure: d =&gt; "" })

// Calculate the maximum count from your dataset
cause_maxCountRE = Math.max(...causeCounts.objects().map(d =&gt; d.count));

plot_cause = Plot.plot({
  marks: [
    Plot.barY(causeCounts, {
      x: "cause",
      y: "count",
      fill: "cause",
