    range: [
      "darkred",
      "darkorange",
      "goldenrod",
      "forestgreen",
      "blue",
      "indigo"
    ]
  },
  marginBottom: 300,
  x: { label: "", tickSize: 2, tickRotate: -35, padding: 0.3,
    domain: ["economic inequality", "political repression", "extremist ideologies", "ethnic or religious tensions", "historical grievances", "other"]
  },  
  y: {
    label: "",
    tickSize: 10,
    tickFormat: d =&gt; d,
    tickValues: Array.from(
      new Set(causeCounts.objects().map(d =&gt; d.count))
    ).sort((a, b) =&gt; a - b),
    domain: [0, cause_maxCountRE]
